"""Read-only object drift and whole-robot contact timing in the C transfer."""
from pathlib import Path
import argparse,json
import numpy as np
import mujoco as mj
p=argparse.ArgumentParser();p.add_argument('--trial',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--end',type=float,default=59.5);a=p.parse_args();m=mj.MjModel.from_binary_path(str((a.trial/'effective_model.mjb').resolve()));z=dict(np.load(a.trial/'physical_trace.npz'));c=dict(np.load(a.trial/'physical_contacts.npz'));t=z['time_s'];q=z['qpos'];k=int(np.argmin(abs(t-40)));end=int(np.argmin(abs(t-a.end)));obj=m.body('target_object_01').id;oq=int(m.jnt_qposadr[int(m.body_jntadr[obj])]);delta=q[k:end+1,oq:oq+3]-q[k,oq:oq+3];dist=np.linalg.norm(delta,axis=1);bn=[m.body(i).name or'world'for i in range(m.nbody)];gn=[m.geom(i).name or'unnamed'for i in range(m.ngeom)];robot=np.asarray([i for i,n in enumerate(bn)if i!=0 and not n.startswith('target_object')]);tm=t[np.minimum(c['step'],len(t)-1)];period=(tm>=40)&(tm<=a.end);robotmask=np.isin(c['body'][:,0],robot)|np.isin(c['body'][:,1],robot);objmask=np.any(c['body']==obj,axis=1);tableids=[i for i,n in enumerate(gn)if n.startswith('table_support')];tablemask=np.isin(c['geom'][:,0],tableids)|np.isin(c['geom'][:,1],tableids);groups={}
for i in np.flatnonzero(period&robotmask&(objmask|tablemask)):
    b1,b2=map(int,c['body'][i]);g1,g2=map(int,c['geom'][i]);r1=b1 in robot;rb,ob=(b1,b2)if r1 else(b2,b1);rg,og=(g1,g2)if r1 else(g2,g1);key=(bn[rb],bn[ob],gn[rg],gn[og]);row=groups.setdefault(key,{'robot_body':bn[rb],'other_body':bn[ob],'robot_geom':gn[rg],'other_geom':gn[og],'first_time_s':float(tm[i]),'last_time_s':float(tm[i]),'normal_force_peak_N':0.,'normal_impulse_Ns':0.,'penetration_max_m':0.,'contact_count':0,'world_impulse_on_nonrobot_Ns':np.zeros(3)});F=(1 if r1 else-1)*(c['frame'][i].reshape(3,3).T@c['force'][i,:3]);row['last_time_s']=float(tm[i]);row['normal_force_peak_N']=max(row['normal_force_peak_N'],float(c['force'][i,0]));row['normal_impulse_Ns']+=float(c['force'][i,0])*m.opt.timestep;row['penetration_max_m']=max(row['penetration_max_m'],float(max(0,-c['distance'][i])));row['contact_count']+=1;row['world_impulse_on_nonrobot_Ns']+=F*m.opt.timestep
for r in groups.values():r['world_impulse_on_nonrobot_Ns']=r['world_impulse_on_nonrobot_Ns'].tolist()
thresholds={}
for bound in [.001,.003,.005,.008,.010]:
    hit=np.flatnonzero(dist>=bound);thresholds[str(bound)]=float(t[k+int(hit[0])])if len(hit)else None
samples=[]
for request in np.arange(40,a.end+.01,.5):
    i=int(np.argmin(abs(t-request)));samples.append({'time_s':float(t[i]),'object1_origin_m':q[i,oq:oq+3].tolist(),'delta_from40_xyz_m':(q[i,oq:oq+3]-q[k,oq:oq+3]).tolist()})
out={'schema':'fourth.C_object1_transfer_drift_contacts.v1','scope':'All robot bodies considered, including palms/wrists/forearms/left arm; recorded actual contacts only. Object drift does not itself prove robot contact.','trial':str(a.trial),'window_s':[float(t[k]),float(t[end])],'object1_final_delta_xyz_m':delta[-1].tolist(),'object1_final_displacement_m':float(dist[-1]),'object1_max_displacement_m':float(dist.max()),'first_displacement_threshold_times_s':thresholds,'robot_object1_or_table_contacts':sorted(groups.values(),key=lambda r:r['first_time_s']),'object_samples':samples};a.output.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({k:v for k,v in out.items()if k!='object_samples'}),flush=True)
